// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the caller address to exercise different msg.sender contexts. The property:
    // After initialize(...) returns, calling proxiableUUID() from the SAME EOA (non-delegated call)
    // should succeed on the reference implementation for any caller/address passed to initialize.
    // The mutant that omitted __UUPSUpgradeable_init() may leave internal initializer state such that
    // proxiableUUID() reverts for some callers — the fuzzer will find such an address.
    function testFuzz_property(address caller, address accessControl) public {
        // keep addresses in wide admissible domain but avoid zero addresses which are less interesting
        if (caller == address(0)) caller = address(1);
        if (accessControl == address(0)) accessControl = address(2);

        // run initialize as the fuzzed caller
        vm.prank(caller);
        bool okInitialize;
        try c.initialize(accessControl) {
            okInitialize = true;
        } catch {
            // if initialize itself reverts, treat that as failure of the setup and skip assertion
            // (we only assert property when initialize succeeded)
            okInitialize = false;
        }

        // Only assert the property when initialize completed successfully.
        // Now call proxiableUUID as the same caller (non-delegated call). On the correct contract
        // this should succeed (not revert) for all inputs; the mutant may cause a revert for some caller.
        if (okInitialize) {
            bool okProxiable;
            try c.proxiableUUID() returns (bytes32) {
                okProxiable = true;
            } catch {
                okProxiable = false;
            }

            // The single assertion: reference always yields true; the mutant will produce false for some fuzz inputs
            assertTrue(okProxiable);
        } else {
            // If initialize reverted, we don't assert property (to avoid false failures); make a vacuous pass
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller who invokes initialize; the reference runs __UUPSUpgradeable_init()
    // and ensures proxiableUUID() is callable afterwards; the mutant omitting that call
    // can make proxiableUUID() revert for some caller contexts. We therefore assert
    // that after initialize invoked by the fuzzed caller, calling proxiableUUID() from
    // the test (non-delegated) context returns the expected slot (i.e., does NOT revert).
    function testFuzz_property(address caller) public {
        // keep wide: caller cannot be zero address because EOA zero is awkward
        vm.assume(caller != address(0));

        // make caller an EOA with some balance so call can be made
        vm.deal(caller, 1 ether);

        // perform initialize as the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.initialize(caller) {
            ok = true;
        } catch {
            // if initialize itself reverts, test that as failing (but reference must not)
            ok = false;
        }

        // if initialize reverted, proxiableUUID cannot be expected; require initialize to succeed
        // we keep property on cases where initialize succeeds (reference must succeed for all callers)
        vm.assume(ok);

        // Now call proxiableUUID from this test (not via delegatecall) and ensure it does NOT revert
        // The reference contract runs __UUPSUpgradeable_init() inside initialize; that sets up internal
        // state so proxiableUUID() (which has notDelegated modifier) can be called off-chain and return.
        bool pqOk;
        try c.proxiableUUID() returns (bytes32 slot) {
            // must equal the ERC1967 implementation slot constant from the original code
            // we cannot import the constant, but we only need to assert call succeeded (non-reverting)
            pqOk = true;
        } catch {
            pqOk = false;
        }

        // Single assertion: reference contract must always allow proxiableUUID() after initialize;
        // the mutant (missing __UUPSUpgradeable_init()) will fail for some caller values and
        // the fuzzer will find such a caller making pqOk == false, causing the test to fail on mutant.
        assertTrue(pqOk);
    }
}

