pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address which invokes initialize; the reference must permit proxiableUUID() to be
    // called non-delegated after initialize for every such caller, the mutant omitting __UUPSUpgradeable_init()
    // will cause proxiableUUID() to revert for some caller addresses.
    function testFuzz_property(address caller) public {
        // admissible domain: any address (keep wide). exclude zero because proxiableUUID call from address(0)
        // is not a realistic EOA actor in forge/prank semantics; still allow it if fuzzer picks it.
        // Ensure caller has some ETH so that any msg.value checks elsewhere won't revert (conservative).
        vm.deal(caller, 1 ether);

        bool ok;
        // call initialize as the fuzzed caller
        vm.prank(caller);
        try c.initialize(address(0x1234)) {
            ok = true;
        } catch {
            // if initialize itself reverts, mark as not-ok; but reference should accept any caller
            ok = false;
        }

        // Now try calling proxiableUUID() in a non-delegated context (direct call). On the reference,
        // this must succeed (not revert) for every caller that invoked initialize above. The mutant omits
        // __UUPSUpgradeable_init() and can cause proxiableUUID() to revert for some callers — the fuzzer
        // will find such a caller causing a difference. We perform the call directly (no prank) because
        // proxiableUUID is a view external requiring non-delegated context; capture revert via try/catch.
        bool proxiableSucceeds;
        try c.proxiableUUID() returns (bytes32) {
            proxiableSucceeds = true;
        } catch {
            proxiableSucceeds = false;
        }

        // Single assertion: on the correct reference, whenever initialize succeeded (ok==true),
        // proxiableUUID() must succeed (non-reverting). The mutant will have cases where initialize
        // returned ok==true but proxiableSucceeds==false.
        assertTrue(!ok || proxiableSucceeds);
    }
}

