pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: an arbitrary address to use as _accessControl
    function testFuzz_property(address accessControl) public {
        // avoid zero address to keep domain wide but meaningful
        vm.assume(accessControl != address(0));

        bool ok1;
        // first initialize should succeed
        try c.initialize(accessControl) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        // second initialize: on the correct contract this must revert (cannot re-initialize)
        try c.initialize(accessControl) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General rule: reference sets the initialized flag so the second initialize must fail (ok2 == false) for ALL inputs where first succeeded.
        // The mutant omits setting the flag, so there exist inputs where ok1 == true and ok2 == true (re-initialization allowed).
        assertTrue(!(ok1 && ok2));
    }
}

