        // keep addresses non-zero to be meaningful but otherwise wide
        if (accessControl == address(0)) accessControl = address(1);
        if (caller == address(0)) caller = address(2);

        // 1) First initialize should succeed (top-level call). We call from `caller` and supply accessControl.
        bool firstOk;
        try c.initialize(accessControl) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // If first initialize reverted, nothing guarantees anything about subsequent calls; restrict to cases
        // where the first initialize succeeded to test reinitialization protection.
        vm.assume(firstOk);

        // 2) Now attempt to initialize again from the same caller. For the reference contract this MUST revert
        // because it marks _initialized = 1 on the first successful top-level initialize; the mutant fails to
        // mark initialized and may allow this to succeed. We capture whether the second call succeeds.
        bool secondOk;
        try c.initialize(accessControl) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // General rule assertion: the reference contract enforces that a second initialize call (after a successful
        // top-level initialize) reverts, so secondOk must be false for all admissible inputs. The buggy mutant
        // will sometimes have secondOk == true.
        assertTrue(!secondOk);
    }
