pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the caller and the accessControl address. The property:
    // After a successful top-level initialize by some caller with some accessControl,
    // any second top-level initialize (by possibly another caller and same accessControl) MUST revert on the reference.
    // The mutant that does not mark initialized may allow the second call to succeed for some inputs.
    function testFuzz_property(address caller, address accessControl) public {
        // keep addresses non-zero to be sensible but otherwise wide
        vm.assume(accessControl != address(0));
        vm.assume(caller != address(0));

        // First, perform a top-level initialize as `caller`.
        // We emulate an EOA caller by vm.prank(caller). The reference should accept this first call.
        bool firstOk;
        vm.prank(caller);
        try c.initialize(accessControl) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // If the first initialize reverted, it means input was not a top-level admissible call (e.g. construction check) ---
        // the universal property is about successful first top-level initializes, so we only assert when first succeeded.
        if (!firstOk) return;

        // Now attempt to call initialize a second time from a (possibly different) fuzzed caller address.
        // The reference MUST revert on re-initialization; the mutant (missing _initialized set) may allow success.
        bool secondOk;
        address caller2 = address(uint160(uint256(keccak256(abi.encodePacked(caller, accessControl, block.timestamp)))));
        vm.prank(caller2);
        try c.initialize(accessControl) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // Assert the reference property: second initialize MUST revert (i.e., secondOk == false).
        // This holds for the correct contract for all admissible inputs; the mutant will allow some inputs where secondOk == true.
        assertTrue(!secondOk);
    }
}

