pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the accessControl address passed to initialize.
    // General rule: After calling initialize(accessControl) on a freshly-deployed implementation instance
    // via a top-level external call (not delegatecall), calling proxiableUUID() on the implementation contract
    // (which is not delegated) must return the ERC1967 implementation slot value (a bytes32). The mutant that
    // omits writing _initialized can break initialization invariants and cause context checks to revert; thus
    // for some accessControl fuzz inputs the mutant will make proxiableUUID() revert while the reference always
    // allows the call and returns the slot. We therefore assert that proxiableUUID() call succeeds and returns
    // the expected slot bytes32(ERC1967Utils.IMPLEMENTATION_SLOT) as a non-zero value.
    function testFuzz_property(address accessControl) public {
        // keep domain wide but avoid zero address since many accessControl implementations might not accept it
        if (accessControl == address(0)) return;

        // Call initialize on c with the fuzzed accessControl
        bool ok;
        bytes32 slot;
        try c.initialize(accessControl) {
            ok = true;
        } catch {
            // If initialize itself reverts on some inputs, we treat that as not admissible for this property
            // (we only assert about cases where initialize completes). Return to avoid false failures.
            return;
        }

        // After a successful initialize, proxiableUUID() is a notDelegated function — calling it on the implementation
        // (address(c) == __self) should succeed and return a non-zero bytes32 (the IMPLEMENTATION_SLOT constant).
        // We call it via low-level try/catch to observe revert behavior on the mutant.
        try c.proxiableUUID() returns (bytes32 returned) {
            slot = returned;
        } catch {
            // If this reverts, the mutant has broken the invariant; assert will catch this because slot will be zero
            // but we must produce exactly one assertTrue reading c; so set slot to zero to fail the assertTrue below.
            slot = bytes32(0);
        }

        // single assertion: the returned slot must be non-zero (reference: always returns IMPLEMENTATION_SLOT; mutant may revert or return 0)
        assertTrue(slot != bytes32(0));
    }
}

