pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IVaultMinimal {
    function currentUtilizationIndex(address _asset) external returns (uint256);
    function utilization(address _asset) external view returns (uint256);
}

// A minimal vault that allows controlling currentUtilizationIndex and utilization
contract VaultHelper is IVaultMinimal {
    uint256 public idx;
    uint256 public util;
    function set(uint256 _idx, uint256 _util) external {
        idx = _idx;
        util = _util;
    }
    function currentUtilizationIndex(address) external override returns (uint256) {
        return idx;
    }
    function utilization(address) external view override returns (uint256) {
        return util;
    }
}

contract InvMutTest is Test {
    C c;
    VaultHelper v;

    function setUp() public {
        c = new C();
        v = new VaultHelper();
    }

    // Fuzzed parameters:
    // prevIndex: previous stored index in utilizationData.index
    // prevLast: previous stored lastUpdate in utilizationData.lastUpdate
    // newIndex: index returned by vault.currentUtilizationIndex
    // utilView: value returned by vault.utilization
    // We allow wide ranges; we avoid prevLast == type(uint).max to keep block.timestamp arithmetic safe.
    function testFuzz_property(uint256 prevIndex, uint256 prevLast, uint256 newIndex, uint256 utilView) public {
        // Keep previous lastUpdate reasonably bounded below current block timestamp
        // We'll advance time so block.timestamp > prevLast in the scenario we need.
        prevLast = bound(prevLast, 0, block.timestamp);

        // choose asset as any address (fuzz not allowed for adversary here)
        address asset = address(0x1234);
        address vaultAddr = address(v);

        // Initialize vault helper with newIndex and utilView
        v.set(newIndex, utilView);

        // Write into c's storage by calling rate once to ensure mapping entries exist,
        // but we need to set the internal utilizationData to our desired prevIndex/prevLast.
        // There's no setter so we will simulate by directly manipulating storage via call sequence:
        // First, ensure an entry exists: call rate so mapping entry is created with defaults.
        vm.warp(block.timestamp + 1);
        try c.rate(vaultAddr, asset) returns (uint256) {
        } catch {}

        // Now overwrite the stored utilizationData.index and lastUpdate via writing into storage slots.
        // Compute the storage slot for getVaultAdapterStorage().utilizationData[vault][asset]
        // VaultAdapterStorageLocation constant in original is 0x2b1d5d801322d1007f654ac87d8072a5f5ca4203517edc869ef2aa54addad600
        bytes32 base = 0x2b1d5d801322d1007f654ac87d8072a5f5ca4203517edc869ef2aa54addad600;

        // Layout: mapping(address => mapping(address => UtilizationData)) utilizationData is at some slot inside struct;
        // For simplicity, we will locate the utilizationData mapping slot by replicating how Solidity computes slots.
        // We know the library places the VaultAdapterStorage at that exact slot; utilizationData is the first member per IVaultAdapter.VaultAdapterStorage.
        // So slot of utilizationData mapping is keccak256(abi.encode(key, mapping_slot)) pattern where mapping_slot = keccak256(base)??
        // To avoid complex slot calc errors, we'll instead rely on calling rate to set values deterministically by manipulating time and vault helper.

        // Instead of direct storage writes (risky), we'll drive the state to the intended prevIndex/prevLast by calling rate under controlled conditions.
        // Set vault to return index = prevIndex, warp time to prevLast, and call rate to record those values.

        // Ensure prevLast < block.timestamp after warp
        uint256 startTime = bound(prevLast, 0, block.timestamp);
        vm.warp(startTime);
        // Set vault helper to return prevIndex and utilView
        v.set(prevIndex, utilView);
        // Call rate so that utilizationData.index = prevIndex and lastUpdate = startTime
        try c.rate(vaultAddr, asset) returns (uint256) {
        } catch {}

        // Now advance time to a later timestamp so block.timestamp > prevLast
        vm.warp(startTime + 5);

        // Set vault to return newIndex and utilView for the next call
        v.set(newIndex, utilView);

        // Now call reference contract's rate and record the returned value.
        // The general property: when block.timestamp > previous lastUpdate, elapsed = block.timestamp - previous lastUpdate
        // So reference will compute a non-zero elapsed (5) and use it in _applySlopes.
        // Mutant forces elapsed=0 causing different result whenever elapsed != 0 and utilization index changed such that utilization computed from index differs from utilization view.

        // We cannot call the mutant here; instead we assert a property that must hold on the reference for ALL inputs:
        // After calling rate now, utilizationData.lastUpdate must equal current block.timestamp (startTime + 5).
        // This is observable via calling rate again and ensuring it behaves as if lastUpdate was updated: specifically, calling rate twice without time advance should result in identical utilization because elapsed=0 second time.

        // Call rate first time at time startTime+5
        uint256 first = c.rate(vaultAddr, asset);

        // Immediately call rate second time (no warp) — reference will see block.timestamp == lastUpdate and thus will read utilization via IVault.utilization (utilView)
        uint256 second = c.rate(vaultAddr, asset);

        // The general rule (property): if two consecutive calls to rate happen at the same block.timestamp, the returned values must be equal (because state and inputs didn't change between calls).
        // This holds for the reference implementation for ALL inputs. The mutant can break this when it incorrectly sets elapsed causing the first call to use elapsed=0 even though it should have used non-zero, leading to different state updates and possibly different second call results.

        // Assert the rule: first and second must be equal
        assertTrue(first == second);
    }
}

