pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IVaultView {
    function currentUtilizationIndex(address _asset) external view returns (uint256);
    function utilization(address _asset) external view returns (uint256);
}

// Minimal Vault stub that allows setting index and utilization; used by fuzz to control external behaviour.
contract VaultStub {
    uint256 public idx;
    uint256 public util;
    function set(uint256 _idx, uint256 _util) external {
        idx = _idx;
        util = _util;
    }
    function currentUtilizationIndex(address) external view returns (uint256) {
        return idx;
    }
    function utilization(address) external view returns (uint256) {
        return util;
    }
    function addAsset(address) external {}
}

contract InvMutTest is Test {
    C c;
    VaultStub vault;

    function setUp() public {
        c = new C();
        vault = new VaultStub();
    }

    // Fuzz parameters:
    // - prevIndex: previous stored utilizationData.index for (vault, asset)
    // - currIndex: current index returned by the vault stub
    // - prevLast: previous utilizationData.lastUpdate (as a timestamp)
    // - warpTo: the block.timestamp at call time
    // We do NOT hardcode asset addresses; we use an arbitrary address fuzzed via assetSeed.
    function testFuzz_property(uint256 prevIndex, uint256 currIndex, uint256 prevLast, uint256 warpTo, uint256 assetSeed) public {
        // Keep domain wide but avoid division-by-zero in the reference implementation when elapsed == 0 path
        // We need elapsed > 0 so that the reference executes the branch using (index - prevIndex) / elapsed.
        // Enforce warpTo > prevLast so elapsed = warpTo - prevLast > 0.
        vm.assume(warpTo > prevLast);

        // Also ensure currIndex != prevIndex so utilization computation uses (index - prevIndex) (non-negative but can be zero)
        // We let fuzzer pick values; it's fine if equal sometimes — the property still holds; but to make difference likely,
        // don't restrict equality. Only ensure elapsed != 0 handled above.

        // Choose an asset address from assetSeed (fuzzed address via uint to avoid hardcoding)
